const HUES=[30,45,60,75,135,180,195,240,270,285,315,345];
const COLORS=['#EF8734','#F5C242','#FFFF55','#CCFC4F','#75FC60','#77FBFE','#55BBF9','#0000F5','#7515F5','#B023F6','#EB33BB','#FF003F'];
