const MODES=['Black','White','Opposite'];
const foreground=(i,m)=>m===0?'#080808':m===1?'#fff':OPPOSITES[i];
const glyph=(i,kind)=>kind==='study1'?'<g transform="translate(-7.2 0) scale(.6)"><path d="M128.021 36.8398V50.7998H99.5801V123.16H84.1807V50.7998H55.9805V36.8398H128.021Z" fill="currentColor"/></g>':ICONS[i].art;
function specimen(i,m,kind){return `<span class="icon-specimen-disc" style="background:${COLORS[i]}"><svg viewBox="0 0 96 96" aria-hidden="true" style="color:${foreground(i,m)}">${glyph(i,kind)}</svg></span>`;}
function comparison(i,kind){return `<div class="icon-compare-head"><div><strong>${HUES[i]}° · ${kind==='study1'?'Fixed letter T':ICONS[i].name}</strong><p>${kind==='study1'?'Same letter, size and stroke. Compare only the foreground color.':'Compare the same symbol against black, white and opposite-color foregrounds.'}</p></div><button type="button" data-icon-close aria-label="Close color comparison">Close ×</button></div><div class="icon-compare-options">${MODES.map((mode,m)=>`<figure>${specimen(i,m,kind)}<figcaption>${mode}</figcaption></figure>`).join('')}</div>`;}
function matrix(kind){return `<div class="icon-color-lab" data-icon-lab="${kind}"><div class="icon-lab-instruction"><strong>12 selected hues</strong><span>Hover, focus or tap a color to compare</span></div><div class="icon-hue-grid">${HUES.map((h,i)=>`<button class="icon-hue" type="button" data-hue="${i}" aria-expanded="false" aria-controls="${kind}-comparison" aria-label="Compare ${h} degree hue"><span style="background:${COLORS[i]}" aria-hidden="true"></span><small>${h}°</small></button>`).join('')}</div><div class="icon-hue-comparison" id="${kind}-comparison" hidden></div></div>`;}

